// This function separates a string of nested parentheses into individual groups.
// Each group contains properly matched pairs of parentheses. It throws an error 
// if there are unmatched or mismatched brackets.

List<String> separateParenGroups(String parenString) {
  if (parenString.isEmpty) return [];

  final List<String> groups = <String>[];
  int balance = 0;
  String currentGroup = '';

  for (final char in parenString.split('')) {
    if (char == '(' || char == '[' || char == '{') {
      if (balance > 0 && !isMatchingPair(currentGroup.isNotEmpty ? currentGroup[currentGroup.length - 1] : '', char)) {
        groups.add(currentGroup);
        currentGroup = '';
      }
      currentGroup += char;
      balance++;
    } else if (char == ')' || char == ']' || char == '}') {
      if (balance <= 0) {
        throw StateError('Mismatched closing parenthesis at position $index');
      }

      if (!isMatchingPair(currentGroup.isNotEmpty ? currentGroup[currentGroup.length - 1] : '', char)) {
        throw StateError('Mismatched parentheses type');
      }

      currentGroup = currentGroup.substring(0, currentGroup.length - 1);
      balance--;
    }
  }

  if (balance != 0) {
    throw StateError('Unmatched opening parenthesis');
  }

  if (currentGroup.isNotEmpty) {
    groups.add(currentGroup);
  }

  return groups;
}

bool isMatchingPair(String open, String close) {
  return (open == '(' && close == ')') ||
         (open == '[' && close == ']') ||
         (open == '{' && close == '}');
}
