String generateBalancedParentheses(int n) {
  List<String> parts = [];

  for (int i = 0; i < n; i++) {
    // Add opening parenthesis
    parts.add('(');

    // Add some inner nesting between this pair
    int innerPairs = Random().nextInt(n-1)+1;
    parts.addAll(generateBalancedParentheses(innerPairs));

    // Close current pair
    parts.add(')');
  }

  return parts.join('');
}
