  int i = 0;
  while (i < numbers.length - 1) {
    final current = numbers[i];
    final next = numbers[i + 1];

    if (current == next) {
      for (int j = i; j < numbers.length - 1; j++) {
        numbers[j] = numbers[j + 1];
