bool willItFly(List<int> q, int w) {
  if (q.isEmpty || q.length != 4) return false;

  final a = q[0];
  final b = q[1];
  final c = q[2];
  final d = q[3];

  // Check for the first condition: sum of any three is greater than the fourth
  bool cond1 = (a + b > c && a + c > b && b + c > a &&
      a + b > d && a + d > b && b + d > a &&
      a + c > d && a + d > c && c + d > a &&
      b + c > d && b + d > c && c + d > b);

  // Check for second condition: product of all four numbers should be even
  bool cond2 = ((a * b * c * d) % 2 == 0);

  // Additional check: no number can exceed half of the total sum or be less than zero
  final totalSum = a + b + c + d;
  bool cond3 = !((a > totalSum / 2 || b > totalSum / 2 ||
       c > totalSum / 2 || d > totalSum / 2) || 
       (a < 0 || b < 0 || c < 0 || d < 0));

  return cond1 && cond2 && cond3;
}
