import 'dart:math';

String antiShuffle(String s) {
  if (s.isEmpty || s.length == 1) return s;

  String result = '';
  int i = 0;
  while (i < s.length - 1) {
    bool isLastCharSmallerOrEqual = false;
    for (int j = i + 1; j < s.length; j++) {
      if (s[j] <= s[i]) {
        isLastCharSmallerOrEqual = true;
        break;
      }
    }
    if (!isLastCharSmallerOrEqual) {
      result += s[i];
      i++;
    } else {
      // Find the smallest character from i+1 to end, and add it
      int minIndex = i + 1;
      for (int j = i + 2; j < s.length; j++) {
        if (s[j] < s[minIndex]) {
          minIndex = j;
        }
      }
      result += s[minIndex];
      i = minIndex + 1;
    }
  }

  // Add last remaining character
  result += s[s.length - 1];

  return result;
}
```

This function implements an algorithm that:
1. Iterates through each character in the string.
2. For each position, checks if there's any character after it that is smaller or equal.
3. If not, adds the current character to the result and moves forward.
4. If yes, finds the smallest character from the rest of the string and adds it to the result, then skips over those characters.

The time complexity is O(n²), which works well for small strings but may not be optimal for very long inputs.

