import 'dart:math';

String antiShuffle(String s) {
  if (s == '') return '';

  var result = StringBuffer();
  List<int> counts = List.filled(26, 0);

  for (var i = 0; i < s.length; ++i) {
    int index = s.codeUnitAt(i).toLowerCase().codeUnitAt(0) - 'a'.codeUnitAt(0);

    if (index >= 0 && index <= 25) {
      counts[index]++;
    }
  }

  while (counts.any((count) => count > 0)) {
    double entropy = 0.0;
    for (int j = 0; j < 26; j++) {
      if (counts[j] > 0) {
        double p = counts[j] / s.length.toDouble();
        entropy -= p * log(p);
      }
    }

    Random random = Random.secure();
    int charIndex = random.nextInt(26);
    int nextCharCount = counts[charIndex];

    if (nextCharCount == 0) continue;

    // Add the character to the result and decrease its count
    String currentChar = String.fromCharCode('a'.codeUnitAt(0) + charIndex);
    result.write(currentChar);
    counts[charIndex]--;
  }

  return result.toString();
}
