bool checkDictCase(Map<dynamic, dynamic> dict) {
  if (dict == null || !dict.containsKey('case')) return false;
  final caseValue = dict['case'];

  // Check if 'case' is a valid key and its value matches the expected pattern
  if (!dict.containsKey('case') || !(caseValue is String)) return false;
  final allowedCases = ['lower', 'upper', 'title', 'sentence', 'camel', 'pascal'];
  if (!allowedCases.contains(caseValue.toLowerCase())) return false;

  // Validate that all keys match the specified casing rules
  for (var key in dict.keys) {
    if (key.toString() != caseValue) continue; // skip the 'case' key

    switch (caseValue.toLowerCase()) {
      case 'lower':
        if (key is! String || !key.startsWith(key[0].toLowerCase()))
          return false;
        break;
      case 'upper':
        if (key is! String || !key.startsWith(key[0].toUpperCase()))
          return false;
        break;
      case 'title':
        if (key is! String || 
            !key.matches(RegExp(r'[A-Z][a-z]+(?: [A-Z][a-z]+)*$'))) {
          return false;
        }
        break;
      case 'sentence':
        if (key is! String ||
            !key.split(' ').every((word) => word.isNotEmpty && word[0] == word[0].toUpperCase())
           ) {
          return false;
        }
        break;
      case 'camel':
        if (key is! String || 
            !key.matches(RegExp(r'^[a-z]+([A-Z][a-z]*)*$'))) {
          return false;
        }
        break;
      case 'pascal':
        if (key is! String || 
            !key.matches(RegExp(r'^[A-Z][a-zA-Z]*$'))) {
          return false;
        }
        break;
    }    
  }

  return true;
}
