import 'dart:math';

int chooseNum(int x, int y) {
  if (x < 0 || y < 0) return -1;

  final n = max(x, y);
  final k = min(x, y);

  // If k is 0 or equal to n, the result is 1
  if (k == 0 || k == n) return 1;

  // Calculate factorial of numbers up to n
  var numerator = 1;
  for (var i = n; i > n - k; i--) {
    numerator *= i;
  }

  var denominator = 1;
  for (var i = 1; i <= k; i++) {
    denominator *= i;
  }

  return numerator ~/ denominator;
}

