    if (row < 0 || row >= rows || col < 0 || col >= cols || visited[row * cols + col] || grid[row][col] <= 0) return;

    visited[row * cols + col] = true;

    for (final dir in directions) {
      final newRow = row + dir[0];
      final newCol = col + dir[1];
      if (!visited[newRow * cols + newCol]) {
        dfs(newRow, newCol);
      }
    }
  }

  for (var i = 0; i < rows * cols; i++) {
    final row = i ~/ cols;
    final col = i % cols;
    if (!visited[i] && grid[row][col] > 0) {
      dfs(row, col);
      count++;
    }
  }

  return min(count, capacity);
}
