    int currentRowSum = 0;
    for (int col = 0; col < cols; col++) {
      currentRowSum += grid[row][col];
    }

    // Calculate how much we can fill in this row without exceeding capacity
    int fillAmount = min(currentRowSum, capacity);
    int remainingCapacity = capacity - fillAmount;

    // Distribute the fill amount across columns proportionally to their values
    for (int col = 0; col < cols; col++) {
