      if (minRowSum >= remainingCapacity) {
        break;
      }

      int idx = rowSums.indexWhere((val) => val == minRowSum);
      int take = min(minRowSum, remainingCapacity);
      remainingCapacity -= take;
      rowSums[idx] -= take;

      // Remove this row from consideration since it's filled to its limit
      rowSums.removeAt(idx);
      rows--;
    }

    return capacity - remainingCapacity;
  }
