int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Initialize the result to zero.
  var maxFilled = 0;

  for (var i = 0; i < rows; ++i) {
    for (var j = 0; j < cols; ++j) {
      // Check if current cell is not empty and can be filled.
      if (grid[i][j] != -1 && grid[i][j] <= capacity) {
        // Find how many consecutive cells in this row we can fill starting from [i,j].
        var count = 1;
        while (j + count < cols && grid[i][j + count] != -1 && grid[i][j + count] <= capacity) {
          ++count;
        }

        // Update maxFilled with maximum of previous value or current count.
        maxFilled = max(maxFilled, count);

        // If we've filled all possible columns in this row, break early.
        if (j + count >= cols) break;
      }
    }
  }

  return maxFilled;
}
