    int rightIndex = mid + 1;
    int k = leftStart;

    while (leftIndex <= mid && rightIndex <= rightEnd) {
      if (copy[leftIndex] <= copy[rightIndex]) {
        copy[k++] = copy[leftIndex++];
      } else {
        copy[k++] = copy[rightIndex++];
      }
    }

    // Copy remaining elements from the left half
    while (leftIndex <= mid) {
      copy[k++] = copy[leftIndex++];
    }

    // Copy remaining elements from the right half
    while (rightIndex <= rightEnd) {
      copy[k++] = copy[rightIndex++];
    }
  }

  void mergeSort(int start, int end) {
    if (start < end) {
      int mid = (start + end) ~/ 2;
      mergeSort(start, mid);
      mergeSort(mid + 1, end);
      merge(start, mid, end);
    }
  }

  mergeSort(0, copy.length - 1);
  return copy;
