      depth++;
    } else if (char == ')') {
      if (stack.isNotEmpty && stack.last != -1) {
        // Ensure that the closing parenthesis corresponds to an opening one in the same pair.
        stack.removeLast();
        depth--;
      } else {
        return false;
      }
    }
  }

  return stack.isEmpty && depth == 0;
}
