  String currentWord = '';

  for (int i = 0; i < text.length; i++) {
    final char = text[i];

    if (char == ' ') {
      if (inWord && currentWord.isNotEmpty) {
        words.add(currentWord);
        currentWord = '';
        inWord = false;
      }
    } else if (char.isLetterOrDigit || char == '-') { // Include hyphen as part of word
      currentWord += char;
      inWord = true;
    } else {
      if (inWord && currentWord.isNotEmpty) {
        words.add(currentWord);
        currentWord = '';
        inWord = false;
      }
    }
  }

  // Add the last word if there's any remaining
  if (inWord && currentWord.isNotEmpty) {
    words.add(currentWord);
  }

