String fixSpaces(String text) {
  final lines = text.split('\n');

  String processLine(String line) {
    if (line.isEmpty || line.trim().isEmpty) return '';

    // Split the line into tokens and reconstruct with single space
    List<String> parts = [];
    int i = 0;
    while (i < line.length) {
      if (line[i] == ' ') {
        parts.add(' ');
        i++;
      } else {
        int j = i + 1;
        while (j < line.length && !isWhitespace(line[j])) j++;
        parts.add(line.substring(i, j));
        i = j;
      }
    }

    // Join parts with spaces, but ensure no multiple consecutive spaces
    String result = parts.join('');
    int lastSpaceIndex = -1;
    for (int k = 0; k < result.length; k++) {
      if (result[k] == ' ') {
        lastSpaceIndex = k;
      }
    }

    // Trim leading/trailing whitespace
    if (lastSpaceIndex != -1 && lastSpaceIndex == result.length - 1) {
      result = result.substring(0, lastSpaceIndex);
    }

    return result;
  }

  return lines.map(processLine).join('\n');
}

